    'The WebView game may still be active. Leave only when you want to close this room.':
        'Partia w WebView może nadal trwać. Wyjdź tylko wtedy, gdy chcesz zamknąć ten pokój.',
    'The app opens Chess.com directly, so account and match settings stay on the website.':
        'Aplikacja otwiera bezpośrednio Chess.com, dlatego ustawienia konta i partii pozostają w witrynie.',
    'The app reads the live FEN and sends supported board moves back into the page.':
        'Aplikacja odczytuje FEN na żywo i przesyła obsługiwane ruchy z szachownicy z powrotem na stronę.',
    'The app verifies board state from the physical board before the lesson continues.':
        'Przed kontynuowaniem lekcji aplikacja sprawdza pozycję na fizycznej szachownicy.',
    'The backend fetches public Lichess games and counts usable PGNs before you confirm.':
        'Przed potwierdzeniem serwer pobiera publiczne partie Lichess i zlicza przydatne pliki PGN.',
    'The backend uses 80% build data and 20% test data.':
        'Serwer wykorzystuje 80% danych do budowy i 20% danych testowych.',
    'The board is ready when its Bluetooth light is blinking. A solid light usually means it is already connected.':
        'Szachownica jest gotowa, gdy jej kontrolka Bluetooth miga. Ciągłe światło zwykle oznacza, że jest już połączona.',
    'The check-in task refreshes at local noon, and still requires at least 24 hours since the last claim.':
        'Zadanie meldowania odświeża się w lokalne południe, a od ostatniego odbioru nadal muszą minąć co najmniej 24 godziny.',
    'The physical board can now guide the setup from the imported position.':
        'Fizyczna szachownica może teraz prowadzić ustawianie zaimportowanej pozycji.',
    'The production page listens to Move piece coordinates and animates pieces to their current squares.':
        'Strona produkcyjna odbiera współrzędne figur Move i animuje figury do ich bieżących pól.',
    'The tactical point is that the rook cannot move without mate threats.':
        'Motyw taktyczny polega na tym, że wieża nie może się ruszyć bez dopuszczenia groźby mata.',
